\documentclass{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    axis lines = middle,
    xlabel = \(x\),
    ylabel = \(f(x)\),
    xmin = -2, xmax = 3,
    ymin = -1, ymax = 4,
    xtick = {-2,-1,0,1,2,3},
    ytick = {-1,0,1,2,3,4},
    grid = both,
    minor tick num = 1,
    legend pos = north east,
    legend style = {cells={align=left}},
    title = {分段函数 \(f(x)\) 的图像}
]

% 右支：x >= 0, f(x) = 1-x
\addplot[domain=0:3, samples=100, thick, smooth, blue] {1-x};
\addlegendentry{\(1-x\;(x \ge 0)\)}

% 左支：x < 0, f(x) = 2^x
\addplot[domain=-2:0, samples=100, thick, smooth, red] {2^x};
\addlegendentry{\(2^x\;(x < 0)\)}

% 可选：在 (0,1) 处加实心点，强调该点属于右支
\addplot[mark=*, only marks, mark size=1.5pt, blue] coordinates {(0,1)};

\end{axis}
\end{tikzpicture}
\end{document}
